get_dashboard_report_quick.code:
use WebCommander\Resources\DashboardReports\DashboardReports;

$response = DashboardReports::getDashboardReportQuick($client, ['duration' => 'last_12_months', 'kpis' => 'total_sales,aov', 'entity_name' => 'product']);

foreach ($response->map['kpis'] as $kpi) {
    echo $kpi['label'], ' ', $kpi['value'], ' (', $kpi['change_percent'], '% vs previous period)', PHP_EOL;
}

get_dashboard_report_summary.code:
use WebCommander\Resources\DashboardReports\DashboardReports;

$response = DashboardReports::getDashboardReportSummary($client, ['duration' => 'last_12_months']);

$sales = $response->map['quick_report']['sales'];
